INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('a0e465c2-0eeb-4976-b8bb-b2114e827d53', 'JH-2026-GUM-0002', 'SUBMITTED', 'बसिया के पास कोयल नदी का जो मिट्टी का बांध है, उसमें पुलिया के पास बड़ी दरार आ गई है। पिछले बरसात के बाद से दरार हर महीने लंबी होती जा रही है। बारिश में पानी अगर इस दरार से घुसा तो पूरा टोला डूब जाएगा। हम लोग पत्थर डाल रहे हैं पर काम नहीं हो रहा।', 'hi', NULL, 'कोयल नदी के बांध में दरार बढ़ रही है', NULL, NULL, false, NULL, 'Mangra Oraon', NULL, 'GUM', 'GUM-BAS', '22.789000', '84.759000', NULL, 250, 'yearly', NULL, 'WATER', 'FLOOD', NULL, '0.78', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 5, false, NULL, false, NULL, NULL, false, '2026-09-05T12:53:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('5c532087-440a-4d14-957f-5e6466cd7fb6', 'JH-2026-LAT-0001', 'SUBMITTED', 'Between Mahuadanr and Netarhat the ghat road slides at the same three bends every July. Last year it was closed for eleven days, a woman in labour had to be carried down on a cot. The PWD puts back the mud and it goes again. Someone should study why those three bends slide and how to hold them, and we need a way to know the night before it will go.', 'en', 'Between Mahuadanr and Netarhat the ghat road slides at the same three bends every July. Last year it was closed for eleven days, a woman in labour had to be carried down on a cot. The PWD puts back the mud and it goes again. Someone should study why those three bends slide and how to hold them, and we need a way to know the night before it will go.', 'Netarhat ghat road slips every monsoon and cuts off the plateau villages', NULL, NULL, false, NULL, 'Emmanuel Kerketta', NULL, 'LAT', 'LAT-MAH', '23.472000', '84.263000', NULL, 8000, 'yearly', NULL, 'ACCESSIBILITY', 'LANDSLIDE', NULL, '0.74', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 15, false, NULL, false, NULL, NULL, false, '2026-09-05T13:05:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('20a89692-0e46-4cd5-893c-b3b39a810eea', 'JH-2026-SAH-0001', 'SUBMITTED', 'Our village on the Ganga bank near Rajmahal is being cut away. In two years twelve houses and the primary school ground have fallen into the river. Every monsoon the bank falls in pieces at night and we hear it. The sandbags the department put last year were gone in a month. We do not know which houses go next. We want to know where the river will cut and something that actually holds the bank.', 'en', 'Our village on the Ganga bank near Rajmahal is being cut away. In two years twelve houses and the primary school ground have fallen into the river. Every monsoon the bank falls in pieces at night and we hear it. The sandbags the department put last year were gone in a month. We do not know which houses go next. We want to know where the river will cut and something that actually holds the bank.', 'The Ganga is eating our village at Rajmahal, twelve houses gone in two years', NULL, NULL, false, NULL, 'Mohammad Sahabuddin', NULL, 'SAH', 'SAH-RAJ', '25.048000', '87.838000', NULL, 1800, 'yearly', NULL, 'URBAN_INFRA', 'FLOOD', NULL, '0.86', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 14, false, NULL, false, NULL, NULL, false, '2026-09-05T13:08:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('f279eaf4-d063-4988-b6a6-7f1a5cdc7cf9', 'JH-2026-RAN-0001', 'SUBMITTED', 'I live in Harmu Housing Colony in Ranchi. Whenever it rains hard for a few hours the Harmu river comes over the wall and the drains flow backwards into our lanes and ground floors. This happened four times last monsoon. The river was made narrow and cemented and now it has nowhere to go. We want to understand where the water comes from and where it should go, so the corporation stops guessing.', 'en', 'I live in Harmu Housing Colony in Ranchi. Whenever it rains hard for a few hours the Harmu river comes over the wall and the drains flow backwards into our lanes and ground floors. This happened four times last monsoon. The river was made narrow and cemented and now it has nowhere to go. We want to understand where the water comes from and where it should go, so the corporation stops guessing.', 'Harmu river overflows into the colony every big rain, drains flow backwards', NULL, NULL, false, NULL, 'Sanjay Prasad Sahu', NULL, 'RAN', 'RAN-RAT', '23.352000', '85.298000', NULL, 6000, 'seasonal', NULL, 'URBAN_INFRA', 'FLOOD', NULL, '0.64', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 16, false, NULL, false, NULL, NULL, false, '2026-09-05T13:09:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('b9b5efd6-38b5-443a-bb1d-9bfa69c79772', 'JH-2026-GUM-0001', 'SUBMITTED', 'I am from Basia. The mud embankment on the South Koel river beside our tola has a crack that started after last monsoon near the culvert. It was one hand wide in October, now I can put my whole arm in it and it is getting longer towards the village side. When the river rises in July the water will come straight through it into forty houses and the school. Nobody from the block has come to see it even after we told the mukhiya twice.', 'en', 'I am from Basia. The mud embankment on the South Koel river beside our tola has a crack that started after last monsoon near the culvert. It was one hand wide in October, now I can put my whole arm in it and it is getting longer towards the village side. When the river rises in July the water will come straight through it into forty houses and the school. Nobody from the block has come to see it even after we told the mukhiya twice.', 'Crack spreading along the South Koel embankment near Basia', NULL, NULL, false, 'usr_c02789e4fd796c94bb11a0f0', 'Sunita Oraon', NULL, 'GUM', 'GU