INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('7d6fb1d7-7818-4c35-b206-7f46a9bfa535', 'JH-2026-GUM-0003', 'SUBMITTED', 'I am the ASHA worker for this panchayat. The river bund on the Koel near the Basia culvert is splitting open. In the last rain I saw muddy water seeping from the lower side of the crack even though the river was not full. If this bund goes, the lower tola with mostly Oraon families and the anganwadi will be under water. Please send someone who understands bunds, not just a JCB.', 'en', 'I am the ASHA worker for this panchayat. The river bund on the Koel near the Basia culvert is splitting open. In the last rain I saw muddy water seeping from the lower side of the crack even though the river was not full. If this bund goes, the lower tola with mostly Oraon families and the anganwadi will be under water. Please send someone who understands bunds, not just a JCB.', 'Koel river bund near Basia culvert is splitting, water seeps in rains', NULL, NULL, false, NULL, 'Anita Kujur', NULL, 'GUM', 'GUM-BAS', '22.784000', '84.766000', NULL, 280, 'yearly', NULL, 'WATER', 'FLOOD', NULL, '0.80', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 4, false, NULL, false, NULL, NULL, false, '2026-09-05T12:54:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
