e, NULL, NULL, false, NULL, 13, false, NULL, false, NULL, NULL, false, '2026-09-05T13:14:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('87c90468-b214-46ee-b433-73c6e96c807f', 'JH-2026-BOK-0001', 'CITIZEN_VERIFIED', 'The government primary school of our village in Gomia is below the Konar canal. Every August water from the canal overflow and the field above comes into the classrooms and the school closes for two to three weeks. Books and midday meal stock get spoiled. Children of class one and two stop coming after that and some do not come back. Either the water has to be sent somewhere else or the school has to be lifted.', 'en', 'The government primary school of our village in Gomia is below the Konar canal. Every August water from the canal overflow and the field above comes into the classrooms and the school closes for two to three weeks. Books and midday meal stock get spoiled. Children of class one and two stop coming after that and some do not come back. Either the water has to be sent somewhere else or the school has to be lifted.', 'Primary school below the Konar canal floods and closes every August', NULL, NULL, false, NULL, 'Rekha Kumari', NULL, 'BOK', 'BOK-GOM', '23.808000', '85.836000', NULL, 180, 'yearly', NULL, 'EDUCATION', 'FLOOD', NULL, '0.58', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 3, false, NULL, false, NULL, NULL, true, '2026-02-25T13:17:58.107Z', '2026-09-05T13:23:01.566Z', false, false, '2026-09-05T13:23:01.566Z', NULL, NULL, NULL, false, false, false, false, NULL);
