INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('539f69c9-4d55-4035-9443-72c5fd88ef62', 'JH-2026-RAM-0001', 'SUBMITTED', 'Around Kuju and Mandu there are old CCL open cast pits that were never filled back. They fill with water in monsoon and two boys drowned last year. On the pit edge the ground is sinking and a footpath collapsed. People still graze cattle there and cut grass. We want to know which parts are unsafe and how to fence or fill them, the company says it is not their pit anymore.', 'en', 'Around Kuju and Mandu there are old CCL open cast pits that were never filled back. They fill with water in monsoon and two boys drowned last year. On the pit edge the ground is sinking and a footpath collapsed. People still graze cattle there and cut grass. We want to know which parts are unsafe and how to fence or fill them, the company says it is not their pit anymore.', 'Abandoned open cast pits near Mandu fill with water, ground sinks around them', NULL, NULL, false, NULL, 'Rajesh Kumar Munda', NULL, 'RAM', 'RAM-MAN', '23.748000', '85.612000', NULL, 2000, 'constant', NULL, 'ENVIRONMENT', 'MINING_SUBSIDENCE', NULL, '0.74', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 10, false, NULL, false, NULL, NULL, false, '2026-09-05T12:58:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
