ant', NULL, 'ENVIRONMENT', 'NONE', NULL, '0.62', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 13, false, NULL, false, NULL, NULL, false, '2026-09-05T12:59:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
