ARE', 'DROUGHT', NULL, '0.76', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 6, false, NULL, false, NULL, NULL, false, '2026-09-05T13:00:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
