INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('10be2e1d-5b4c-41a2-bd85-1fc2c571cde6', 'JH-2026-GOD-0001', 'SUBMITTED', 'We are Sauria Paharia living on the hill in Sunderpahari. Our only water is a spring below the village. From April it is a trickle and we dig in the sand for water. Every year in May-June children get loose motions and two or three die before they reach the road, which is nine kilometres of walking. The PHE tank on the hill has never had water. We need a way to keep the spring alive and to know early when the sickness is starting.', 'en', 'We are Sauria Paharia living on the hill in Sunderpahari. Our only water is a spring below the village. From April it is a trickle and we dig in the sand for water. Every year in May-June children get loose motions and two or three die before they reach the road, which is nine kilometres of walking. The PHE tank on the hill has never had water. We need a way to keep the spring alive and to know early when the sickness is starting.', 'Hill spring above our Paharia hamlet dries by April and loose motions start in every house', NULL, NULL, false, NULL, 'Sombari Pahariya', NULL, 'GOD', 'GOD-SUN', '24.858000', '87.462000', NULL, 350, 'seasonal', NULL, 'HEALTHCARE', 'EPIDEMIC', NULL, '0.84', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 5, false, NULL, false, NULL, NULL, false, '2026-09-05T13:03:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('31f810e2-586d-49a3-8f66-35fe92131ca8', 'JH-2026-DUM-0001', 'SUBMITTED', 'Ale ato re dak'' banuk''a. Kuĩ do rohor ena, chapakol ho dak'' bang oḍok''a. Maejiu ko sangin khon dak'' ko agu eda, Kathikund hor re. Dhiri buru latar re dak'' menak''a mente ko men eda, menkhan okoe ho bang ñam let''a. (हमारे गांव में पानी नहीं है, कुआं सूख गया, चापाकल से भी पानी नहीं निकलता। औरतें काठीकुंड सड़क तक दूर से पानी ला रही हैं। लोग कहते हैं पहाड़ के नीचे पानी है पर किसी को मिला नहीं।)', 'sat', NULL, 'Ale ato re dak'' banuk''a — kuĩ rohor ena', NULL, NULL, false, NULL, 'Lakhan Hembrom', NULL, 'DUM', 'DUM-KAT', '24.403000', '87.452000', NULL, 400, 'seasonal', NULL, 'WATER', 'DROUGHT', NULL, '0.70', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 4, false, NULL, false, NULL, NULL, false, '2026-09-05T13:04:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('06c2cda2-35e7-4462-9f44-ae975f1c48e1', 'JH-2026-LAT-0002', 'SUBMITTED', 'We live on the edge of the tiger reserve forest near Garu. Every March-April fire comes through the sal forest, mostly started for mahua collection or by passers-by. Our mahua trees, tendu and the lac on kusum get burnt, and twice the fire reached the cattle shed. Forest guard says he has no people. We want to know where the fire will come from and a way to stop it before it reaches us, not after.', 'en', 'We live on the edge of the tiger reserve forest near Garu. Every March-April fire comes through the sal forest, mostly started for mahua collection or by passers-by. Our mahua trees, tendu and the lac on kusum get burnt, and twice the fire reached the cattle shed. Forest guard says he has no people. We want to know where the fire will come from and a way to stop it before it reaches us, not after.', 'Fires in the sal forest near Garu every March burn our mahua and reach the village edge', NULL, NULL, false, NULL, 'Budhni Birjia', NULL, 'LAT', 'LAT-GAR', '23.629000', '84.192000', NULL, 700, 'yearly', NULL, 'ENVIRONMENT', 'FOREST_FIRE', NULL, '0.72', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 6, false, NULL, false, NULL, NULL, false, '2026-09-05T13:06:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('1283defd-7f60-4c83-83cb-1895e7b1c6be', 'JH-2026-KHU-0001', 'CLOSED', 'In Murhu our families have kept lac on kusum and ber trees for generations. For three years the brood dies in the rains, sometimes from too much rain in September, sometimes because winter came too late. Half the families have stopped and gone to Ranchi for daily wage. The price is fine, it is the crop that is failing. Someone should tell us when to put the brood now that the weather has changed.', 'en', 'In Murhu our families have kept lac on kusum and ber trees for generations. For three years the brood dies in the rains, sometimes from too much rain in September, sometimes because winter came too late. Half the families have stopped and gone to Ranchi for daily wage. The price is fine, it is the crop that is failing. Someone should tell us when to put the brood now that the weather has changed.', 'Lac on our kusum trees is failing because the rains have gone wrong', NULL, NULL, false, NULL, 'Etwa Munda', NULL, 'KHU', 'KHU-MUR', '22.975000', '85.372000', NULL, 900, 'yearly', NULL, 'LIVELIHOODS', 'DROUGHT', NULL, '0.60', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 5, false, NULL, false, NULL, NULL, false, '2026-02-26T13:17:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('f199338b-7963-414b-b167-096fb17ac44c', 'JH-2026-ESB-0001', 'SUBMITTED', 'Around Dhalbhumgarh the elephant herd comes from the Dalma side into our paddy every October-November when the grain is filling. In one night twenty families lose their year. Compensation comes after a year and is small. Forest department comes in the morning. We need a way to know the herd is coming that evening, and something that keeps them out that does not kill anyone.', 'en', 'Around Dhalbhumgarh the elephant herd comes from the Dalma side into our paddy every October-November when the grain is filling. In one night twenty families lose their year. Compensation comes after a year and is small. Forest department comes in the morning. We need a way to know the herd is coming that evening, and something that keeps them out that does not kill anyone.', 'Elephants eat the standing paddy every October and nobody comes before morning', NULL, NULL, false, NULL, 'Dasrath Soren', NULL, 'ESB', 'ESB-DHA', '22.529000', '86.641000', NULL, 1100, 'seasonal', NULL, 'AGRICULTURE', 'NONE', NULL, '0.58', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 8, false, NULL, false, NULL, NULL, false, '2026-09-05T13:12:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('41f6cfa0-23b9-45d6-ae85-eb6bc33af68f', 'JH-2026-PAK-0001', 'SUBMITTED', 'In Littipara block all houses got a toilet under the mission in 2019. There is no water within the tola from February to June so nobody uses them, everyone goes to the field again, and in the rains the whole tola gets loose motions. The toilets are now used to keep goats. Building was easy, water was not thought about. We need a toilet that works with the little water we have.', 'en', 'In Littipara block all houses got a toilet under the mission in 2019. There is no water within the tola from February to June so nobody uses them, everyone goes to the field again, and in the rains the whole tola gets loose motions. The toilets are now used to keep goats. Building was easy, water was not thought about. We need a toilet that works with the little water we have.', 'Toilets were built but there is no water, so everyone has gone back to the fields', NULL, NULL, false, NULL, 'Salomi Murmu', NULL, 'PAK', 'PAK-LIT', '24.651000', '87.612000', NULL, 800, 'seasonal', NULL, 'SANITATION', 'EPIDEMIC', NULL, '0.66', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 7, false, NULL, false, NULL, NULL, false, '2026-09-05T13:13:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
