INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('680655e4-1525-4dd6-8def-f09c8af624c2', 'JH-2026-DEO-0001', 'SUBMITTED', 'In our village in Palojori block every house got a tap under Jal Jeevan Mission in early 2024. The pipes are laid, the tank is built, and not a single day has water come. The junior engineer does not pick up the phone. The contractor got his payment. This is not a research problem, someone simply has to switch it on and be answerable for it.', 'en', 'In our village in Palojori block every house got a tap under Jal Jeevan Mission in early 2024. The pipes are laid, the tank is built, and not a single day has water come. The junior engineer does not pick up the phone. The contractor got his payment. This is not a research problem, someone simply has to switch it on and be answerable for it.', 'Jal Jeevan Mission taps were fitted in 2024 but not one day of water has come', NULL, NULL, false, NULL, 'Dinesh Mandal', NULL, 'DEO', 'DEO-PAL', '24.207000', '86.973000', NULL, 700, 'constant', NULL, 'PUBLIC_SERVICE', 'NONE', NULL, '0.40', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 5, false, NULL, false, NULL, NULL, false, '2026-09-05T13:16:58.107Z', '2026-09-05T13:23:01.566Z', false, false, NULL, NULL, NULL, NULL, false, false, false, false, NULL);
INSERT INTO "challenges" ("id", "tracking_id", "status", "body_original", "body_lang", "body_en", "title", "framed_statement", "success_criteria", "framing_approved_by_citizen", "reporter_id", "reporter_name", "assisted_by", "district_code", "block_code", "lat", "lng", "location_accuracy_m", "people_affected", "recurrence", "urgency_self_report", "domain", "hazard", "hazard_strength", "severity", "priority_score", "priority_breakdown", "scoring_version", "is_grievance", "forwarded_ref", "cluster_id", "is_parent", "parent_id", "corroboration_count", "official_endorsed", "endorsed_by", "capital_works", "solvability", "embedding", "impact_confirmed", "created_at", "updated_at", "impact_partial", "impact_disputed", "citizen_verified_at", "citizen_verification_note", "sla_breached_at", "escalation_stage", "open_to_all", "grand_challenge", "fork_open", "at_risk_flag", "routed_at") VALUES ('50bb0227-48cd-4e53-bdd7-88acdefe8871', 'JH-2026-SIM-0001', 'CITIZEN_VERIFIED', 'In Bano block our village is on the far side of a river from the high school and the health sub-centre. From July to September the water is chest deep and children cross on a bamboo raft or do not go. Two years ago a boy was swept away. We have asked for a bridge for ten years. Till a bridge comes, is there a safer crossing we can build ourselves, and how do we know the day the river is too high?', 'en', 'In Bano block our village is on the far side of a river from the high school and the health sub-centre. From July to September the water is chest deep and children cross on a bamboo raft or do not go. Two years ago a boy was swept away. We have asked for a bridge for ten years. Till a bridge comes, is there a safer crossing we can build ourselves, and how do we know the day the river is too high?', 'Children cross the swollen river to school on a bamboo raft because there is no bridge', NULL, NULL, false, NULL, 'Prakash Dungdung', NULL, 'SIM', 'SIM-BAN', '22.672000', '84.897000', NULL, 650, 'seasonal', NULL, 'ACCESSIBILITY', 'FLOOD', NULL, '0.76', NULL, NULL, NULL, false, NULL, NULL, false, NULL, 7, false, NULL, false, NULL, NULL, true, '2026-02-22T13:17:58.107Z', '2026-09-05T13:23:01.566Z', false, false, '2026-09-05T13:23:01.566Z', NULL, NULL, NULL, false, false, false, false, NULL);
